func TestLapsEffortsAndTrainingRoundTrip(t *testing.T) {
	ctx := context.Background()
	s := newStore(t)
	// Three rides: 2025, and two in 2026 (local years).
	var ids []int64
	for i, c := range []struct {
		local   string
		fiveKm  float64
		fiveMin float64
	}{{"2025-06-01 10:00", 500, 300}, {"2026-05-01 10:00", 600, 280}, {"2026-05-02 10:00", 550, 320}} {
		local, _ := time.Parse("2006-01-02 15:04", c.local)
		rec := recording(fmt.Sprintf("fit:1:2:%d", i), "x", 2)
		rec.Activity.StartTime = local.Add(-2 * time.Hour)
		rec.Activity.Training = Training{Effect: 3.3, Load: 50, NormalizedPower: 215, RPE: 3}
		rec.Laps = []Lap{{StartS: 0, EndS: 600, TimerS: 590, DistanceM: 5000, AvgHR: 140}, {Auto: false, StartS: 600, EndS: 900, TimerS: 300, DistanceM: 2000}}
		rec.Efforts = []Effort{
			{Group: "bike", Kind: EffortDistance, Key: 5000, Value: c.fiveKm, StartS: 0, EndS: c.fiveKm},
			{Group: "bike", Kind: EffortPower, Key: 300, Value: c.fiveMin, StartS: 10, EndS: 310},
		}
		id, _, err := s.SaveRecording(ctx, rec)
		if err != nil {
			t.Fatal(err)
		}
		ids = append(ids, id)
	}

	a, err := s.Get(ctx, ids[0])
	if err != nil || a.Training != (Training{Effect: 3.3, Load: 50, NormalizedPower: 215, RPE: 3}) {
		t.Fatalf("training %+v %v", a.Training, err)
	}
	laps, err := s.Laps(ctx, ids[0])
	if err != nil || len(laps) != 2 || laps[1].StartS != 600 || laps[0].AvgHR != 140 {
		t.Fatalf("laps %+v %v", laps, err)
	}

	// Ride 2 (2026): 5 km in 600 s and 280 W are the weakest values overall
	// (rank 3) and within 2026 (rank 2).
	eff, err := s.Efforts(ctx, ids[1])
	if err != nil || len(eff) != 2 {
		t.Fatalf("efforts %+v %v", eff, err)
	}
	ranks := map[string][2]int{}
	for _, e := range eff {
		ranks[e.Kind] = [2]int{e.RankAll, e.RankYear}
	}
	if ranks[EffortDistance] != [2]int{3, 2} || ranks[EffortPower] != [2]int{3, 2} {
		t.Errorf("ranks %v", ranks)
	}

	top, err := s.TopEfforts(ctx, "bike", EffortDistance, 5000, time.Time{}, time.Time{}, 2)
	if err != nil || len(top) != 2 || top[0].Value != 500 || top[0].ActivityID != ids[0] {
		t.Fatalf("top %+v %v", top, err)
	}
	y2026 := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	top, _ = s.TopEfforts(ctx, "bike", EffortPower, 300, y2026, y2026.AddDate(1, 0, 0), 5)
	if len(top) != 2 || top[0].Value != 320 {
		t.Errorf("power 2026 %+v", top)
	}

	// Re-deriving replaces laps and efforts instead of adding to them.
	rec := recording("fit:1:2:0", "y", 3)
	rec.Efforts = []Effort{{Group: "bike", Kind: EffortPower, Key: 5, Value: 900}}
	if _, st, err := s.SaveRecording(ctx, rec); err != nil || st != Updated {
		t.Fatal(st, err)
	}
	if laps, _ := s.Laps(ctx, ids[0]); len(laps) != 0 {
		t.Errorf("laps not replaced: %d", len(laps))
	}
	if eff, _ := s.Efforts(ctx, ids[0]); len(eff) != 1 || eff[0].Key != 5 {
		t.Errorf("efforts not replaced: %+v", eff)
	}

	old, err := s.Outdated(ctx, 3)
	if err != nil || len(old) != 2 || old[0].ActivityID != ids[1] || old[0].SHA256 != "x" || old[0].Origin != "upload:ride.fit" {
		t.Errorf("outdated %+v %v", old, err)
	}
}

func TestWeatherPendingAndSave(t *testing.T) {
	ctx := context.Background()
	s := newStore(t)
	now := time.Date(2026, 10, 26, 12, 0, 0, 0, time.UTC)
	s.now = func() time.Time { return now }
	ids := seed(t, s, item{"cycling", "2026-05-01 10:00"}, item{"cycling", "2026-05-02 10:00"})
	indoor := recording("fit:1:1:indoor", "y", 1)
	indoor.Track = nil
	if _, _, err := s.SaveRecording(ctx, indoor); err != nil {
		t.Fatal(err)
	}

	p, err := s.WeatherPending(ctx, 6*time.Hour, 10)
	if err != nil || len(p) != 2 || p[0].ActivityID != ids[1] || p[0].Polyline == "" {
		t.Fatalf("pending %+v %v", p, err)
	}
	if err := s.SaveWeather(ctx, ids[1], Weather{Status: WeatherOK, TempMinC: 12, TempMaxC: 16, WindKmh: 14, Code: 3}); err != nil {
		t.Fatal(err)
	}
	if err := s.SaveWeather(ctx, ids[0], Weather{Status: WeatherError, Error: "timeout"}); err != nil {
		t.Fatal(err)
	}
	if p, _ := s.WeatherPending(ctx, 6*time.Hour, 10); len(p) != 0 {
		t.Errorf("fresh error must not be retried yet: %+v", p)
	}
	now = now.Add(7 * time.Hour)
	if p, _ := s.WeatherPending(ctx, 6*time.Hour, 10); len(p) != 1 || p[0].ActivityID != ids[0] {
		t.Errorf("old error must be retried: %+v", p)
	}
	w, ok, err := s.Weather(ctx, ids[1])
	if err != nil || !ok || w.TempMaxC != 16 || w.Code != 3 {
		t.Errorf("weather %+v %v %v", w, ok, err)
	}
	if _, ok, _ := s.Weather(ctx, ids[0]); ok {
		t.Error("failed lookup is no weather")
	}
}
